import java.util.*;

public class Main {
    // Divisors come in pairs (d, n/d); the smaller one is always <= sqrt(n).
    // Time O(sqrt(n)), space O(number of divisors).
    static List<Long> divisors(long n) {
        List<Long> small = new ArrayList<>(), large = new ArrayList<>();
        for (long i = 1; i <= n / i; i++) {       // same as i*i <= n, but cannot overflow
            if (n % i == 0) {
                small.add(i);
                if (i != n / i) large.add(n / i); // perfect square: add the root only once
            }
        }
        Collections.reverse(large);               // partners were found from big to small
        small.addAll(large);
        return small;
    }

    static boolean isPrime(long n) {
        if (n < 2) return false;
        for (long i = 2; i <= n / i; i++)         // any factor pair has a member <= sqrt(n)
            if (n % i == 0) return false;
        return true;
    }

    public static void main(String[] args) {
        long[] tests = {36, 97, 91};
        for (long n : tests) {
            List<Long> d = divisors(n);
            StringBuilder sb = new StringBuilder();
            for (long x : d) sb.append(' ').append(x);
            System.out.println("n = " + n + " divisors:" + sb + " count: " + d.size()
                    + " prime: " + (isPrime(n) ? "yes" : "no"));
        }
    }
}

