function divisors(n) {
  const small = [], large = [];
  for (let i = 1; i * i <= n; i++) {       // safe here: numbers stay far below 2^53
    if (n % i === 0) {
      small.push(i);
      if (i !== n / i) large.push(n / i);  // perfect square: add the root only once
    }
  }
  return small.concat(large.reverse());    // partners were found from big to small
}

function isPrime(n) {
  if (n < 2) return false;
  for (let i = 2; i * i <= n; i++) {       // any factor pair has a member <= sqrt(n)
    if (n % i === 0) return false;
  }
  return true;
}

