// Divisors come in pairs (d, n/d); the smaller one is always <= sqrt(n).
// Time O(sqrt(n)), space O(number of divisors).
vector<long long> divisors(long long n) {
    vector<long long> small, large;
    for (long long i = 1; i <= n / i; i++) {        // same as i*i <= n, but cannot overflow
        if (n % i == 0) {
            small.push_back(i);
            if (i != n / i) large.push_back(n / i); // perfect square: add the root only once
        }
    }
    small.insert(small.end(), large.rbegin(), large.rend());  // partners came big to small
    return small;
}

bool isPrime(long long n) {
    if (n < 2) return false;
    for (long long i = 2; i <= n / i; i++)          // any factor pair has a member <= sqrt(n)
        if (n % i == 0) return false;
    return true;
}

