    for (long long n : {36LL, 97LL, 91LL}) {
        vector<long long> d = divisors(n);
        cout << "n = " << n << " divisors:";
        for (long long x : d) cout << ' ' << x;
        cout << " count: " << d.size() << " prime: " << (isPrime(n) ? "yes" : "no") << "\n";
