public class Main {
    // Trial division: best for one or a few numbers. Time O(sqrt(n)), space O(1).
    static boolean isPrimeTrial(long n) {
        if (n < 2) return false;
        for (long i = 2; i <= n / i; i++)
            if (n % i == 0) return false;
        return true;
    }

    // Sieve: best for many queries on small values. Time O(N log log N), space O(N).
    static boolean[] sieve(int n) {
        boolean[] composite = new boolean[n + 1];
        for (int p = 2; (long) p * p <= n; p++)
            if (!composite[p])
                for (int m = p * p; m <= n; m += p) composite[m] = true; // cross out multiples
        return composite;
    }

    public static void main(String[] args) {
        int limit = 50;
        boolean[] composite = sieve(limit);       // built once
        StringBuilder sb = new StringBuilder();
        for (int i = 2; i <= limit; i++) if (!composite[i]) sb.append(' ').append(i);
        System.out.println("sieve up to " + limit + ":" + sb);
        int[] queries = {15, 37, 49};
        for (int q : queries)                     // each query is now an O(1) lookup
            System.out.println("lookup " + q + ": " + (composite[q] ? "composite" : "prime"));
        long[] big = {1000000007L, 1000000001L};
        for (long n : big)                        // too big to sieve, so divide up to sqrt(n)
            System.out.println("trial division " + n + ": " + (isPrimeTrial(n) ? "prime" : "composite"));
    }
}

