public class Main {
    // Sieve of Eratosthenes that also counts how many cross-outs it performs.
    // Time O(N log log N), space O(N).
    static void run(int n) {
        boolean[] composite = new boolean[n + 1];
        long crossOuts = 0;
        for (int p = 2; (long) p * p <= n; p++) {     // outer loop stops at sqrt(N)
            if (composite[p]) continue;               // only primes cross out
            for (int m = p * p; m <= n; m += p) {     // start at p*p: smaller multiples are done
                composite[m] = true;
                crossOuts++;                          // about N/p of these for each prime p
            }
        }
        int primes = 0;
        for (int i = 2; i <= n; i++) if (!composite[i]) primes++;
        // cross-outs per 100 numbers grows extremely slowly: that is the log log N factor
        System.out.println("N = " + n + " primes = " + primes + " cross-outs = " + crossOuts
                + " per 100 numbers = " + (crossOuts * 100 / n));
    }

    public static void main(String[] args) {
        int[] sizes = {100, 10000, 1000000};
        for (int n : sizes) run(n);
    }
}

