public class Main {
    // Euclid: gcd(a, b) = gcd(b, a mod b), and gcd(a, 0) = a.
    // Time O(log min(a, b)), space O(1).
    static void show(long a, long b) {
        long x = a, y = b;
        int steps = 0;
        while (y != 0) {
            long r = x % y;      // common divisors of (x, y) and (y, r) are the same
            x = y;
            y = r;
            steps++;             // the larger number at least halves every two steps
        }
        System.out.println("gcd(" + a + ", " + b + ") = " + x + " in " + steps + " steps");
    }

    public static void main(String[] args) {
        show(1071, 462);
        show(48, 18);
        show(1000000000000L, 999999999999L);
        // Worst case: consecutive Fibonacci numbers, every quotient is 1
        show(89, 55);
        show(1134903170L, 701408733L);
    }
}

