public class Main {
    static final long M = 1_000_000_007L;   // prime, and just under 2^30

    // The product of two residues is below about 10^18, which fits in a signed 64-bit long.
    static long mul(long a, long b) { return a * b % M; }

    // Fast power, O(log e) time, O(1) space.
    static long power(long a, long e) {
        long result = 1;
        a %= M;
        while (e > 0) {
            if ((e & 1) == 1) result = mul(result, a);
            a = mul(a, a);
            e >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        long a = 999_999_999L, b = 999_999_998L;
        System.out.println("a = " + a + " b = " + b + " M = " + M);
        System.out.println("(a + b) mod M = " + (a + b) % M);   // the sum is below 2^31
        System.out.println("(a * b) mod M = " + mul(a, b));     // needs 64 bits before the %
        long inv = power(a, M - 2);          // Fermat: works only because M is prime
        System.out.println("inverse of a = " + inv);
        System.out.println("a * inverse mod M = " + mul(a, inv));
        System.out.println("12 / 4 done as 12 * inverse(4) = " + mul(12, power(4, M - 2)));
    }
}

