public class Main {
    static final long M = 1_000_000_007L;

    // Each helper returns a value in [0, M). Time O(1), space O(1).
    static long add(long a, long b) { return (a % M + b % M) % M; }
    // In Java, % keeps the sign of the left side, so add M before the final %.
    static long sub(long a, long b) { return ((a - b) % M + M) % M; }
    // Use long: the product of two residues is about 10^18 and overflows an int.
    static long mul(long a, long b) { return (a % M) * (b % M) % M; }

    public static void main(String[] args) {
        long a = 1_000_000_006L, b = 1_000_000_005L, c = 123_456_789L;
        System.out.println("a = " + a + " b = " + b + " c = " + c + " M = " + M);
        System.out.println("add(a, b) = " + add(a, b));
