public class Main {
    // Binary exponentiation: a^b mod m. Time O(log b), space O(1).
    // Safe while m is below about 3 * 10^9, so base * base fits in a long.
    static long modPow(long a, long b, long m) {
        long result = 1 % m;              // 1 % m gives 0 when m = 1
        long base = ((a % m) + m) % m;    // reduce first; this also fixes a negative a
        while (b > 0) {
            if ((b & 1) == 1) result = result * base % m;  // this bit of b is set
            base = base * base % m;       // square for the next bit
            b >>= 1;                      // drop the bit just used
        }
        return result;
    }

    static void show(long a, long b, long m) {
        System.out.println(a + "^" + b + " mod " + m + " = " + modPow(a, b, m));
    }

    public static void main(String[] args) {
        show(2, 10, 1000);
        show(3, 1000000000000000000L, 1000000007L);   // only about 60 rounds
        show(5, 0, 1);                                 // edge: m = 1
        show(-2, 3, 7);                                // edge: negative base
        show(0, 5, 13);                                // edge: a = 0
        show(1000000008L, 2, 1000000007L);             // edge: a >= m
    }
}

