public class Main {
    static final long P = 1_000_000_007L;
    static final int N = 1000;
    static long[] fact = new long[N + 1], invFact = new long[N + 1];

    static long power(long a, long e) {
        long r = 1;
        a %= P;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % P;
            a = a * a % P;
            e >>= 1;
        }
        return r;
    }

    // Precompute once: O(N + log P) time, O(N) space. Each query is then O(1).
    static void build() {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % P;
        invFact[N] = power(fact[N], P - 2);            // one Fermat inverse only
        for (int i = N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % P;  // fill downward
    }

    static long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;                  // guard: impossible choices
        return fact[n] * invFact[r] % P * invFact[n - r] % P;  // reduce after each multiply
    }

    public static void main(String[] args) {
        build();
        int[][] queries = {{5, 2}, {10, 3}, {52, 5}, {1000, 500}, {3, 5}};
        for (int[] q : queries)
            System.out.println("C(" + q[0] + ", " + q[1] + ") mod P = " + nCr(q[0], q[1]));
    }
}

