import java.util.*;

public class Main {
    // Pigeonhole: n + 1 prefix sums but only n remainders, so two prefixes share one.
    // The elements between those two prefixes add up to a multiple of n.
    // Time O(n), space O(n).
    public static void main(String[] args) {
        int[] a = {3, 1, 4, 1, 5};
        int n = a.length;
        int[] first = new int[n];              // first[r] = prefix length where remainder r appeared
        Arrays.fill(first, -1);
        first[0] = 0;                          // the empty prefix has sum 0
        StringBuilder sb = new StringBuilder();
        for (int x : a) sb.append(' ').append(x);
        System.out.println("array:" + sb);
        long sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += a[i - 1];
            int r = (int) (((sum % n) + n) % n);   // keep the remainder non-negative
            if (first[r] != -1) {                  // repeat found: guaranteed by pigeonhole
                int from = first[r], to = i - 1;
                long total = 0;
                StringBuilder part = new StringBuilder();
                for (int j = from; j <= to; j++) { total += a[j]; part.append(' ').append(a[j]); }
                System.out.println("remainder " + r + " seen after " + from + " and after " + i + " elements");
                System.out.println("subarray [" + from + ".." + to + "]:" + part + " sum = " + total
                        + " divisible by " + n);
                return;
            }
            first[r] = i;
        }
    }
}

