public class Main {
    // Floyd's tortoise and hare on the "linked list" i -> nums[i].
    // Time O(n), space O(1), and the array is never modified.
    static int findDuplicate(int[] nums) {
        int slow = nums[0], fast = nums[nums[0]];
        while (slow != fast) {             // phase 1: meet somewhere inside the cycle
            slow = nums[slow];             // one step
            fast = nums[nums[fast]];       // two steps
        }
        slow = 0;                          // phase 2: restart one pointer from index 0
        while (slow != fast) {             // same speed: they meet at the cycle entry
            slow = nums[slow];
            fast = nums[fast];
        }
        return slow;                       // the cycle entry is the duplicate value
    }

    static void show(int[] nums) {
        StringBuilder sb = new StringBuilder();
        for (int x : nums) sb.append(' ').append(x);
        System.out.println("array:" + sb + " -> duplicate: " + findDuplicate(nums));
    }

    public static void main(String[] args) {
        show(new int[]{1, 3, 4, 2, 2});
        show(new int[]{3, 1, 3, 4, 2});
        show(new int[]{2, 2, 2, 2, 2});
        show(new int[]{1, 1});
    }
}

