public class Main {
    // For every d, add 1 to each multiple of d. Work = N/1 + N/2 + ... + N/N, about N ln N.
    // Time O(N log N), space O(N).
    static int[] divisorCounts(int n, long[] work) {
        int[] count = new int[n + 1];
        for (int d = 1; d <= n; d++)
            for (int m = d; m <= n; m += d) {   // d divides m, 2d, 3d, ...
                count[m]++;
                work[0]++;
            }
        return count;
    }

    public static void main(String[] args) {
        long[] work = {0};
        int[] small = divisorCounts(12, work);
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= 12; i++) sb.append(' ').append(small[i]);
        System.out.println("divisor counts for 1..12:" + sb);
        System.out.println("inner loop steps for N = 12: " + work[0]);

        work[0] = 0;
        int n = 100000;
        int[] big = divisorCounts(n, work);
        int best = 1;
        for (int i = 1; i <= n; i++) if (big[i] > big[best]) best = i;  // first number with most divisors
        System.out.println("inner loop steps for N = " + n + ": " + work[0]);
        System.out.println("most divisors up to " + n + ": " + best + " has " + big[best]);
    }
}

