import java.util.*;

public class Main {
    static int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }

    // k divides x*y exactly when k divides gcd(x,k) * gcd(y,k).
    // Time O(N * d(k) + N log k), space O(k); d(k) = number of divisors of k.
    static long countPairs(int[] nums, int k) {
        List<Integer> divs = new ArrayList<>();
        for (int d = 1; d <= k; d++) if (k % d == 0) divs.add(d);   // all possible gcd values
        long[] seen = new long[k + 1];        // seen[g] = earlier elements whose gcd with k is g
        long pairs = 0;
        for (int x : nums) {
            int g = gcd(x, k);                // only this part of x matters
            for (int d : divs)
                if ((long) g * d % k == 0) pairs += seen[d];   // partner groups that work
            seen[g]++;
        }
        return pairs;
    }

    static void show(int[] nums, int k) {
        StringBuilder sb = new StringBuilder();
        for (int x : nums) sb.append(' ').append(x);
        System.out.println("nums:" + sb + " k = " + k + " -> pairs = " + countPairs(nums, k));
    }

    public static void main(String[] args) {
        show(new int[]{1, 2, 3, 4, 5}, 2);
        show(new int[]{1, 2, 3, 4}, 5);
        show(new int[]{6, 10, 15, 4, 9, 25}, 30);
    }
}

