import java.math.BigInteger;

public class Main {
    // "Multiply by doubling": a * b mod m using only additions that stay below 2m.
    // Works for m up to about 4.6 * 10^18. Time O(log b), space O(1).
    static long mulMod(long a, long b, long m) {
        long result = 0;
        a %= m;
        while (b > 0) {
            if ((b & 1) == 1) result = (result + a) % m;  // add a when this bit of b is set
            a = (a + a) % m;                              // double a for the next bit
            b >>= 1;
        }
        return result;
    }

    static void show(long a, long b, long m) {
        long got = mulMod(a, b, m);
        // Cross-check with BigInteger, which is simple but slower
        long want = BigInteger.valueOf(a).multiply(BigInteger.valueOf(b))
                .mod(BigInteger.valueOf(m)).longValue();
        if (got != want) throw new IllegalStateException("mismatch");
        System.out.println(a + " * " + b + " mod " + m + " = " + got);
    }

    public static void main(String[] args) {
        show(7, 8, 10);
        show(987654321987654321L, 123456789123456789L, 1000000000000000003L);
        show(999999999999999999L, 999999999999999999L, 1000000000000000000L);
    }
}

