public class Main {
    static final long P = 1_000_000_007L;
    static final int N = 60;
    static long[] fact = new long[N + 1], invFact = new long[N + 1];

    static long power(long a, long e) {
        long r = 1;
        for (a %= P; e > 0; e >>= 1, a = a * a % P)
            if ((e & 1) == 1) r = r * a % P;
        return r;
    }

    // The fast version under test: factorials and inverse factorials.
    static long fast(int n, int r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % P * invFact[n - r] % P;
    }

    // Stress test: compare with a slow but obviously correct Pascal triangle.
    // Time O(N^2), space O(N^2).
    public static void main(String[] args) {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % P;
        invFact[N] = power(fact[N], P - 2);
        for (int i = N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % P;

        long[][] pascal = new long[N + 1][N + 2];      // brute force: C(n,r) = C(n-1,r-1) + C(n-1,r)
        for (int n = 0; n <= N; n++) {
            pascal[n][0] = 1;
            for (int r = 1; r <= n; r++) pascal[n][r] = (pascal[n - 1][r - 1] + pascal[n - 1][r]) % P;
        }
        int checked = 0, mismatches = 0;
        for (int n = 0; n <= N; n++)
            for (int r = 0; r <= n + 1; r++) {         // r = n + 1 tests the "return 0" guard
                checked++;
                if (fast(n, r) != pascal[n][r]) mismatches++;
            }
        System.out.println("checked " + checked + " (n, r) pairs up to n = " + N + ", mismatches: " + mismatches);
        System.out.println("C(60, 30) mod P: fast = " + fast(60, 30) + " brute = " + pascal[60][30]);
    }
}

